from rest_framework.generics import RetrieveAPIView
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework.exceptions import PermissionDenied, NotFound
from reversion.models import Revision
from .models import InfrastructureCluster

class CloudInfraRevisionDetailView(RetrieveAPIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, revision_id):
        try:
            revision = Revision.objects.prefetch_related('version_set').get(pk=revision_id)
        except Revision.DoesNotExist:
            raise NotFound('Revision not found')

        # Ensure all versions in this revision belong to clusters owned by the user's organization
        allowed_cluster_ids = set(
            InfrastructureCluster.objects.filter(organization=request.user.organization)
            .values_list('id', flat=True)
        )
        for v in revision.version_set.all():
            cluster_id = v.field_dict.get('cluster_id') or (v.object_id if v.content_type.model == 'infrastructurecluster' else None)
            if cluster_id and int(cluster_id) not in allowed_cluster_ids:
                raise PermissionDenied('Access denied to revisions of external infrastructure')
